// generated by scripts/design/gen-tokens.mjs from design/tokens.json, do not edit.
//
// Colour themes (design/DECISIONS.md). Every colour is dynamic: it resolves light or dark from the
// trait collection on iOS and iPadOS and from the effective appearance on macOS, so a view only
// picks the theme. An always-dark theme has the same colours in both and asks for the dark
// appearance with forcedColorScheme, so system controls and materials match.

import SwiftUI
#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

/// A colour theme, chosen in Settings. Independent of light and dark, which follow the system
/// unless the user pins one, except for the always-dark themes (``ThemeGroup/dark``).
enum AppTheme: String, CaseIterable, Identifiable, Sendable {
    /// Almanac: Warm paper and iron-gall ink with a signal orange accent.
    case almanac
    /// Graphite: Neutral greys with an electric blue accent.
    case graphite
    /// Slate: Cool slate paper with a terracotta accent.
    case slate
    /// Forest: Bone paper and deep green ink with an amber accent.
    case forest
    /// Mono: Black and white only, with a quiet blue grey for the Gregorian side.
    case mono
    /// Obsidian: Near black for OLED screens, warm ink and the signal orange. Always dark.
    case obsidian
    /// Midnight: Deep navy with a teal accent and periwinkle for the Gregorian side. Always dark.
    case midnight
    /// Phosphor: Green black like an old terminal, phosphor green and amber. Always dark.
    case phosphor

    /// The theme for new users.
    static let defaultTheme: AppTheme = .almanac

    /// Every theme, in the order Settings lists them.
    static let ordered: [AppTheme] = [.almanac, .graphite, .slate, .forest, .mono, .obsidian, .midnight, .phosphor]

    var id: String { rawValue }

    /// The name shown in Settings.
    var displayName: String {
        switch self {
        case .almanac: "Almanac"
        case .graphite: "Graphite"
        case .slate: "Slate"
        case .forest: "Forest"
        case .mono: "Mono"
        case .obsidian: "Obsidian"
        case .midnight: "Midnight"
        case .phosphor: "Phosphor"
        }
    }

    /// One line describing the theme.
    var summary: String {
        switch self {
        case .almanac: "Warm paper and iron-gall ink with a signal orange accent."
        case .graphite: "Neutral greys with an electric blue accent."
        case .slate: "Cool slate paper with a terracotta accent."
        case .forest: "Bone paper and deep green ink with an amber accent."
        case .mono: "Black and white only, with a quiet blue grey for the Gregorian side."
        case .obsidian: "Near black for OLED screens, warm ink and the signal orange. Always dark."
        case .midnight: "Deep navy with a teal accent and periwinkle for the Gregorian side. Always dark."
        case .phosphor: "Green black like an old terminal, phosphor green and amber. Always dark."
        }
    }

    /// The group Settings lists the theme in.
    var group: ThemeGroup {
        switch self {
        case .almanac, .graphite, .slate, .forest, .mono: .adaptive
        case .obsidian, .midnight, .phosphor: .dark
        }
    }

    /// True for a theme that is always dark, whatever the system or the Appearance setting.
    var isAlwaysDark: Bool { group == .dark }

    /// The colour scheme the theme forces: `.dark` for an always-dark theme, `nil` for one that
    /// follows the system or the Appearance setting. While it is set, apply it to every window
    /// (`preferredColorScheme`, or the UIKit and AppKit appearance overrides) and show the
    /// Appearance control disabled with ``ThemeGroup/summary``.
    var forcedColorScheme: ColorScheme? { isAlwaysDark ? .dark : nil }

    /// The theme's colours.
    var colors: ThemeColors {
        switch self {
        case .almanac: .almanac
        case .graphite: .graphite
        case .slate: .slate
        case .forest: .forest
        case .mono: .mono
        case .obsidian: .obsidian
        case .midnight: .midnight
        case .phosphor: .phosphor
        }
    }
}

/// How Settings groups the themes: the ones that follow light and dark first, then the
/// always-dark ones.
enum ThemeGroup: String, CaseIterable, Identifiable, Sendable {
    /// Light and dark: Follows the system, or the Appearance setting.
    case adaptive
    /// Dark: Always dark, whatever the system or the Appearance setting.
    case dark

    var id: String { rawValue }

    /// The heading shown in Settings.
    var displayName: String {
        switch self {
        case .adaptive: "Light and dark"
        case .dark: "Dark"
        }
    }

    /// One line describing the group; for `.dark`, the note beside the disabled Appearance control.
    var summary: String {
        switch self {
        case .adaptive: "Follows the system, or the Appearance setting."
        case .dark: "Always dark, whatever the system or the Appearance setting."
        }
    }

    /// The themes in this group, in the order Settings lists them.
    var themes: [AppTheme] { AppTheme.ordered.filter { $0.group == self } }
}

