extension ThemeColors {
    /// An sRGB colour as plain values, so the dynamic providers below capture only Sendable data.
    private struct Components: Sendable {
        let red: Double
        let green: Double
        let blue: Double
        let alpha: Double

        init(_ rgb: UInt32, alpha: Double) {
            red = Double((rgb >> 16) & 0xFF) / 255
            green = Double((rgb >> 8) & 0xFF) / 255
            blue = Double(rgb & 0xFF) / 255
            self.alpha = alpha
        }

        #if canImport(UIKit)
        var platformColor: UIColor { UIColor(red: red, green: green, blue: blue, alpha: alpha) }
        #elseif canImport(AppKit)
        var platformColor: NSColor { NSColor(srgbRed: red, green: green, blue: blue, alpha: alpha) }
        #endif
    }

    /// A colour that resolves to `light` or `dark` (0xRRGGBB, sRGB) with the current appearance.
    private static func dynamic(light: UInt32, dark: UInt32, lightAlpha: Double = 1, darkAlpha: Double = 1) -> Color {
        let light = Components(light, alpha: lightAlpha)
        let dark = Components(dark, alpha: darkAlpha)
        #if canImport(UIKit)
        return Color(uiColor: UIColor { traits in
            (traits.userInterfaceStyle == .dark ? dark : light).platformColor
        })
        #elseif canImport(AppKit)
        return Color(nsColor: NSColor(name: nil) { appearance in
            (appearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua ? dark : light).platformColor
        })
        #endif
    }
}
